    guide_text_dad3421a69792702: "Warto znać dwie granice. **{control_a}** pojawia się tylko przy wydarzeniach z datą nadających się do kalendarza; na liście bez takich dat nie jest oferowane — to uczciwa odpowiedź zamiast pustego kanału. Gdy adres trafi do aplikacji kalendarza, {name_b} nie wie, czy zachowała subskrypcję ani jak często ją odświeża. To ustawienie kalendarza, a niektóre pokazują zmianę dopiero po godzinach.",
