    meeting_phase_how_summary: "How this timeline works",
    meeting_phase_how_html: "Each matter follows the Council path: agenda item, matter file, decision (committee action and vote when published), then attachments. Phases use only what Legistar published for this hearing. Identical document links appear once. Empty vote with an action means a voice or committee outcome — CityScroll does not invent roll-call tallies.",
    // Meetings domain explorer (list ontology — process rail + place groups + next-action)
    meetings_domain_kicker: "Public hearings and meetings",
    meetings_domain_heading: "Not every meeting is a hearing",
    meetings_domain_deck: "A public hearing is a scheduled chance to give testimony or evidence on a specific matter. A public meeting is broader — some are open only to observe. Open any listing to see what the body can do next and how you can take part.",
    meetings_method_arc_html: "Public hearings follow a meeting arc — scheduled, agenda, held, then outcomes — with next steps when attendance or testimony is published. Same-board same-day notices collapse into one card. Each notice links to its City Record source.",
