    meeting_body_role_decision_maker: "Can decide",
    meeting_body_role_oversight: "Can question and oversee, but cannot decide",
    public_input_explainer_open: "Jak działa udział mieszkańców",
    public_input_explainer_what_html: "<p>Udział w postępowaniu publicznym oznacza pozostawienie czegoś w oficjalnych aktach: wypowiedź na wysłuchaniu albo pisemna uwaga złożona przed ogłoszonym terminem. To, co dalej dzieje się z tym zapisem, zależy od postępowania, a każde ogłoszenie na tej stronie mówi, które z nich ma zastosowanie.</p>",
    public_input_explainer_destinations_heading: "Gdzie trafia to, co powiesz",
    public_input_explainer_destinations_html: "<ul><li><b>Publiczny zapis uwag</b> — pisemna uwaga złożona w okresie zbierania uwag trafia do akt, które organ musi rozpatrzyć.</li><li><b>Zeznanie na wysłuchaniu</b> — to, co powiesz na wysłuchaniu, trafia do zapisu zeznań z tego wysłuchania.</li><li><b>Stenogram</b> — niektóre postępowania publikują dosłowny zapis posiedzenia.</li><li><b>Protokół</b> — inne organy publikują zamiast tego streszczenie przebiegu.</li><li><b>Dokument decyzji</b> — odrębny zapis, publikowany, gdy organ odnotuje decyzję.</li></ul><p>Niektóre postępowania publikują też raport odpowiadający na otrzymane uwagi. To jedno z tych miejsc, a każde ogłoszenie mówi, czy ma zastosowanie.</p>",
    public_input_explainer_limits_heading: "Granice udziału",
    public_input_explainer_limits_html: "<p>Odpowiedź urzędnika to co innego niż wpis do akt. Złożenie uwagi lub zeznanie umieszcza twoje słowa w aktach, a żaden urzędnik nie ma obowiązku odpowiedzieć ci osobiście. Ta strona takiej odpowiedzi nie obiecuje.</p><p>Liczba uwag pozostaje liczbą uwag. Organ waży to, co powiedziano, wobec prawa, któremu podlega, więc ta strona nie przedstawia żadnych sum uwag jako poparcia ani sprzeciwu i nie traktuje liczby uwag jako głosowania.</p>",
    public_input_explainer_examples_heading: "Trzy sposoby, w jakie działa to w praktyce",
    public_input_explainer_example_hearing: "Zabierz głos na wysłuchaniu Rady Miasta w sprawie projektu uchwały albo wyślij pisemne zeznanie.",
    public_input_explainer_example_hearing_surface: "Zobacz zaplanowane wysłuchania i posiedzenia",
    public_input_explainer_example_rule: "Zgłoś uwagi do projektu przepisu agencji przed ogłoszonym terminem.",
    public_input_explainer_example_rule_surface: "Zobacz otwarte okresy zgłaszania uwag do przepisów",
    public_input_explainer_example_contract: "Zgłoś uwagi do proponowanego przyznania kontraktu w wyznaczonym oknie.",
    public_input_explainer_example_contract_surface: "Zobacz terminy uwag do kontraktów",
    public_input_explainer_official_source: "Źródło urzędowe: {source}",
    public_input_explainer_method_summary: "Skąd pochodzi to wyjaśnienie",
    public_input_explainer_method_html: "<p>Każdy powyższy przykład prowadzi do strony miejskiej, która go reguluje, oraz do części tej strony z bieżącymi zapisami tego rodzaju. To wyjaśnienie opisuje, jak takie postępowania działają ogólnie. Konkretna data, status, cel i droga udziału dla każdego z nich pozostają w jego własnym ogłoszeniu, obok linku do źródła w Rejestrze Miejskim.</p>",
