    land_role_strip_window_days_alt_eis_html: "<b>Obliczony termin:</b> do {days} dni kalendarzowych ({alt} dni, jeśli wymagane jest oświadczenie o oddziaływaniu na środowisko) — nie jest to zaobserwowana data.",
    land_role_strip_window_rules_defined: "Harmonogram wynika z przyjętych zasad proceduralnych, a nie ze stałej liczby dni ustawowych.",
