    nl_aria: "Opisz prostym językiem, czego szukasz",
    invnote_aria: "Notatka do tego przypiętego elementu",
    site_kicker: "Publiczne rejestry NYC, połączone",
    back_home_aria: "Powrót do strony głównej CityScroll",
    brand_home_aria: "Strona główna CityScroll",
    back_to_crol: "← Powrót do CityScroll",
    home_link: "Strona główna",
    data_page_h1: "Dane",
    about_h_what: "Czym to jest",
    about_p_what_html: "CityScroll pomaga sprawdzić, co dzieje się w administracji miasta Nowy Jork i co można zrobić dalej. Zacznij od <b>Teraz</b>, aby zobaczyć pilne terminy, <b>W pobliżu</b>, aby zobaczyć lokalne zmiany, <b>Obserwowane</b>, aby zobaczyć zapisane alerty, lub <b>Przeglądaj</b>, aby znaleźć kontrakty i plany, sprawy gruntów, spotkania i głosowania, egzaminy, sprzedaż miejskich nieruchomości i przepisy. <b>Przewodnik</b> uczy, jak czytać wpis. Serwis korzysta z oficjalnych publikacji miasta, ale jest niezależny i nie jest prowadzony ani wspierany przez miasto Nowy Jork.",
    about_h_content: "O naszej treści",
    about_p_content_html: "CityScroll używa generatywnej sztucznej inteligencji (AI) do tworzenia szkiców nagłówków i prostych wyjaśnień. Przed publikacją człowiek sprawdza i redaguje te treści. AI nie tworzy ani nie zmienia oficjalnych rejestrów wyświetlanych w serwisie.",
    about_h_flags: "Oznaczenia i kontekst, wyjaśnione",
    about_h_tax_lien_formula:"Tax lien sale progression",
    about_p_tax_lien_formula_html: "CityScroll pokazuje, jak często zastawy podatkowe na tym samym etapie trafiały na końcową listę sprzedaży w poprzednim cyklu. Nie przewiduje sprzedaży ani przejęcia nieruchomości.",
    about_p_flags_intro_html: "Ogłoszenia o zamówieniach zawierają dwa rodzaje obliczanych adnotacji. Obie to <b>kontekst statystyczny, nie ustalenia ani oskarżenia</b>. Oznaczenie oznacza jedynie „warto przyjrzeć się bliżej”. Za każdym wzorem stoi uczciwy powód. Sytuacje nadzwyczajne naprawdę się zdarzają. Niektóre rynki są wyspecjalizowane i mają niewielu oferentów. Dopasowywanie nazw nie jest idealne. Ta metoda opiera się na dwóch wytycznych. Jedna to <a href=\"https://www.open-contracting.org/resources/red-flags-in-public-procurement-a-guide-to-using-data-to-detect-and-mitigate-risks/\" target=\"_blank\" rel=\"noopener noreferrer\">przewodnik po czerwonych flagach Open Contracting Partnership<span class=\"sr-only\"> (otwiera się w nowej karcie)</span></a>. Druga to zasady rzetelności <a href=\"https://opentender.eu/\" target=\"_blank\" rel=\"noopener noreferrer\">Opentender<span class=\"sr-only\"> (otwiera się w nowej karcie)</span></a>.",
    about_li_flags_html: "<li><b>⚑ Krótkie okno ogłoszenia</b> — liczba dni między publikacją ogłoszenia a terminem odpowiedzi. Oznaczamy to, gdy jest to 10 dni lub mniej oraz mniej niż połowa własnej mediany danej agencji. Mediana pochodzi z ostatnich 200 ogłoszeń tej agencji. Krótkie okna faworyzują tych, którzy już wiedzieli, że praca nadchodzi.</li><li><b>⚑ Metoda bezkonkursowa</b> — ogłoszenie mówi, że dostawca zostanie wybrany bez pełnego konkursu. Może to być umowa zawarta w drodze negocjacji, jedyne wybrane źródło, pilny zakup lub projekt pilotażowy. Czasami może to być uczciwe. Ale zawsze warto o tym wiedzieć.</li><li><b>⚑ Powtarzające się przyznania</b> — ta sama nazwa dostawcy pojawia się w 3 lub więcej ogłoszeniach o przyznaniu w tej samej agencji w ciągu 90 dni. Może to wskazywać zarówno na zlecenia w ramach umowy ramowej, jak i na faworyzowanie. Oznaczenie po prostu je liczy — Ty decydujesz, co to znaczy.</li><li><b>Pasek kontekstu</b> — jak duże jest przyznanie, pokazane jako percentyl przyznań tej agencji w ciągu ostatnich 12 miesięcy (pokazywany tylko, gdy agencja ma 20 lub więcej przyznań w tym okresie). Pokazuje też udział dostawcy w kwotach przyznanych przez agencję w tym samym okresie. Używamy dokładnie opublikowanej nazwy. Nie łączymy tu wariantów nazw.</li><li><b>Opóźnienie przyjęcia reguł (szacunek)</b> — po zamknięciu okresu komentarzy, jak długo podobne Agency Rules historycznie czekały na Notice of Adoption. Z historii City Record z prawą cenzurą, by niedokończone procesy nie wyglądały na szybsze niż są. Per agencję przy ≥20 przeszłych odstępach, inaczej w skali miasta. Pokazane jako kreskowany segment „Estimate” na osi reguł i jedną linią w digescie tylko przy zmianie pasma — nigdy jako potwierdzona data. Pełna formuła: <a href=\"https://github.com/cityscroll/cityscroll-app/blob/main/docs/formulas/rules-adoption-lag.md\">rules adoption lag</a>.</li>",
    about_p_flags_footer_html: "Wszystkie liczby pochodzą na żywo z <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">otwartych danych City Record<span class=\"sr-only\"> (otwiera się w nowej karcie)</span></a> w momencie wyświetlania ogłoszenia. To przyznania <b>w takiej postaci, w jakiej zostały opublikowane</b>. Liczby mogą być opóźnione względem rejestracji kontraktu i rzeczywistej płatności. Nic tutaj nie mówi, że ktoś postąpił źle. To po prostu oszczędza Ci matematyki.",
    about_h_feedback: "Wyślij opinię",
    about_p_feedback: "Znalazłeś błąd, chcesz nową funkcję, albo masz przemyślenie? Wyślij je tutaj. Czytamy wszystko. Konto nie jest potrzebne.",
