    data_p_lede_html: "Zbiór danych The City Record na pierwszy rzut oka. Twoja przeglądarka pobiera aktualne sumy z <a href=\"https://data.cityofnewyork.us/City-Government/City-Record-Online/dg92-zbpx\" target=\"_blank\" rel=\"noopener noreferrer\">NYC Open Data<span class=\"sr-only\"> (otwiera się w nowej karcie)</span></a>. Nic nie jest zapisywane na serwerze. Liczby są zgodne z <a href=\"api.html#upstream\">zasadami rzetelności</a>. Statystyki pozostają w swojej własnej sekcji. Prawdopodobne błędy wprowadzania danych są wykluczone — kwoty 10 mld USD lub więcej. Zastępcze terminy nie są liczone jako prawdziwe.",
