    stats_path_rules_what: "Ogłoszenie o przepisie wskazuje obowiązek, który go wymagał. Stamtąd można przeczytać ten obowiązek w źródle samego miasta.",
    stats_path_rules_limit: "Opublikowane ogłoszenie nie dowodzi, że obowiązek został spełniony.",
