    stats_path_role_law: "Prawo w swoim źródle",
    stats_method_counted_label: "Co liczą te liczby",
    stats_method_counted_desc: "Każdy zestaw liczy jeden rodzaj rekordu. Ten sam rekord wymieniony dwa razy liczy się raz. Zestawów nigdy się nie sumuje.",
    stats_method_periods_label: "Jakie dni obejmują liczby użycia",
    stats_method_periods_desc: "Każda kolumna podaje własne dni. Ostatni dzień jest liczony do ostatniego sprawdzenia, więc nie jest pełnym dniem. Okres, którego nikt nie zmierzył, pozostaje nieopublikowany i nigdy nie pokazuje się jako zero.",
    stats_method_fresh_label: "Jak aktualne to jest",
    stats_method_fresh_desc: "Każdy zestaw podaje datę dowodów, na których go policzono. Żadna data nie pochodzi z zegara wydawcy ani z procesu budowania.",
    stats_method_limits_label: "Czego ta strona nie powie",
    stats_method_limits_desc: "Nie powie, ile osób przyszło ani czy wyszukiwanie odpowiedziało na pytanie. Liczba wyszukiwań to nie liczba czytelników.",
    stats_method_private_label: "Co pozostaje prywatne",
    stats_method_private_html: "Powyższe liczby wyszukiwań są publikowane, same wyszukiwania nie. Wizyty, obserwacje i sumy wiadomości pozostają prywatne. Przeczytaj <a href=\"api.html#upstream\">noty o źródłach</a> lub otwórz <a href=\"https://api.cityscroll.org/stats\">publiczny JSON</a>.",
